"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, useEffect, useMemo, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/**
 * Props for a streaming reply. Give each answer its own `key`: words are
 * tracked by position, so a new answer in the same instance would not fade in.
 */
export type StreamingReplyProps = Omit<ComponentPropsWithoutRef<"div">, "children"> & {
  /** The answer so far. Pass the whole text each time, not only the new piece. */
  text: string;
  /** True while more text can arrive. The caret shows and the screen reader waits. */
  streaming?: boolean;
};

const EASE_OUT = [0.165, 0.84, 0.44, 1] as const;
// Long enough to read as a fade, short enough that a fast stream never queues up.
const WORD: Transition = { duration: 0.4, ease: EASE_OUT };
const GROW: Transition = { duration: 0.2, ease: EASE_OUT };
// The caret is an oscillation, so it eases both ways.
const BLINK: Transition = { duration: 1, ease: "easeInOut", repeat: Infinity };
const INSTANT: Transition = { duration: 0 };

/**
 * Shows an answer that arrives in pieces. Each new word fades in, a caret marks
 * the end while it streams, and the block grows to fit without a jump. Screen
 * readers hear the answer once, when it is complete.
 */
export function StreamingReply({ text, streaming = false, className, ...divProps }: StreamingReplyProps) {
  const reduceMotion = useReducedMotion();
  // Each token keeps its trailing space, so wrapping matches plain text.
  const words = useMemo(() => text.match(/\S+\s*|\s+/g) ?? [], [text]);
  // Words that were already there at mount belong to a finished answer and stay still.
  const [settled] = useState(() => (streaming ? 0 : words.length));
  const inner = useRef<HTMLDivElement>(null);
  const [height, setHeight] = useState<number | null>(null);

  useEffect(() => {
    const node = inner.current;
    if (!node || !("ResizeObserver" in window)) return;
    const observer = new ResizeObserver(() => setHeight(node.offsetHeight));
    observer.observe(node);
    return () => observer.disconnect();
  }, []);

  // The height only follows a measurement while text arrives. At rest it is
  // `auto`, so a narrower window can re-wrap the text freely.
  const follow = streaming && !reduceMotion && height !== null;

  return (
    <div {...divProps} data-streaming={streaming || undefined} className={cn("text-sm leading-6 text-foreground", className)}>
      <motion.div
        initial={false}
        animate={{ height: follow ? height : "auto" }}
        transition={follow ? GROW : INSTANT}
        className={cn(streaming && "overflow-hidden")}
      >
        {/* The words are split for the fade, which reads badly aloud. The line below carries the answer. */}
        <div ref={inner} aria-hidden="true" className="wrap-break-word whitespace-pre-wrap">
          {words.map((word, index) =>
            index < settled ? (
              <span key={index}>{word}</span>
            ) : (
              <motion.span
                key={index}
                // Opacity only: a blur on body text reads as a rendering fault, not as arrival.
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={WORD}
              >
                {word}
              </motion.span>
            ),
          )}
          {streaming && (
            <motion.span
              data-caret=""
              animate={reduceMotion ? { opacity: 1 } : { opacity: [1, 0.2, 1] }}
              transition={reduceMotion ? INSTANT : BLINK}
              className="ml-0.5 inline-block h-4 w-0.5 translate-y-0.5 rounded-full bg-foreground"
            />
          )}
        </div>
      </motion.div>
      {/* Empty while it streams: a live region that changed with every word would talk over itself. */}
      <p role="status" className="sr-only">
        {streaming ? "" : text}
      </p>
    </div>
  );
}
